// What the device keeps of one house (fio-spec 3.6), in the IndexedDB of this origin: K_D and K_A as non-extractable
// CryptoKeys (structured clone keeps the key object, never its bytes), the whole pub_H (the pin of every handshake),
// houseId, deviceId, aud, the admission ticket, pinnedVer and the house's name (hostile text, rendered only as text).
// NEVER here: ephemerals, Z, session keys, the SAS, R or S.
import type { Bytes } from '../../../src/remote/index.ts'

export interface StoredKey {
  /** Non-extractable: generated by crypto.subtle with extractable = false. */
  privateKey: CryptoKey
  pub: Bytes
}

export interface HouseRecord {
  /** Hex of houseId: the key of the record. */
  id: string
  houseId: Bytes
  pubH: Bytes
  deviceId: Bytes
  kD: StoredKey
  kA: StoredKey
  /** The relay as this device knows it: the URL it dials and the `aud` it signs, never what the relay says. */
  relayUrl: string
  aud: string
  admitTicket: Bytes
  pinnedVer: number
  /** Hostile text from the house. */
  houseName: string
  /** `pending` until the first HS_DONE of a normal session (spec 3.4 step 14, E-15). */
  state: 'pending' | 'active'
  pairedAtMs: number
}

const DB = 'tether-remote'
const STORE = 'houses'

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1)
    req.onupgradeneeded = () => { req.result.createObjectStore(STORE, { keyPath: 'id' }) }
    req.onsuccess = () => resolve(req.result)
    req.onerror = () => reject(req.error ?? new Error('indexedDB.open failed'))
  })
}

async function run<T>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await open()
  try {
    return await new Promise<T>((resolve, reject) => {
      const tx = db.transaction(STORE, mode)
      const req = f(tx.objectStore(STORE))
      let value: T
      req.onsuccess = () => { value = req.result }
      tx.oncomplete = () => resolve(value)
      tx.onerror = () => reject(tx.error ?? new Error('indexedDB transaction failed'))
      tx.onabort = () => reject(tx.error ?? new Error('indexedDB transaction aborted'))
    })
  } finally {
    db.close()
  }
}

/** v1 knows one house per device: the first record, or undefined. */
export async function loadHouse(): Promise<HouseRecord | undefined> {
  const all = await run('readonly', (s) => s.getAll() as IDBRequest<HouseRecord[]>)
  return all[0]
}

export async function saveHouse(r: HouseRecord): Promise<void> {
  await run('readwrite', (s) => s.put(r))
}

/** Removes the house and its keys (CLOSE(0x04), spec 4.7; a pending record that never completed, spec 3.4 step 14). */
export async function deleteHouse(id: string): Promise<void> {
  await run('readwrite', (s) => s.delete(id))
}
